package net.civeira.phylax.feature.observe.observedissue.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.valueobject.UsersVO;

class UsersValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of users of observed issue")
  void test_users_value_holder_assign_plain_value() {
    Object holder = new Object();
    UsersValueHolder<Object> value = new UsersValueHolder<>(holder);
    Assertions.assertSame(holder, value.users(1), "Setters must return the holder");
    Assertions.assertTrue(value.getUsersValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(1, value.getUsers().orElse(null), "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of users of observed issue")
  void test_users_value_holder_assign_value_object() {
    Object holder = new Object();
    UsersValueHolder<Object> value = new UsersValueHolder<>(holder);
    UsersVO vo = UsersVO.from(1);
    Assertions.assertFalse(value.getUsersValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.users(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getUsersValue().orElseThrow());
    Assertions.assertSame(holder, value.users(Optional.empty()));
    Assertions.assertFalse(value.getUsersValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.users(Optional.of(vo)));
    Assertions.assertSame(vo, value.getUsersValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of users of observed issue against the original")
  void test_users_value_holder_read() {
    Object holder = new Object();
    UsersValueHolder<Object> value = new UsersValueHolder<>(holder);
    UsersVO vo = UsersVO.from(1);
    UsersVO other = UsersVO.from(1);
    ObservedIssue original = Mockito.mock(ObservedIssue.class);
    Mockito.when(original.getUsersValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readUsers(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readUsers(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.users(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readUsers(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readUsers(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of users of observed issue")
  void test_users_value_holder_unset() {
    Object holder = new Object();
    UsersValueHolder<Object> value = new UsersValueHolder<>(holder);
    UsersVO vo = UsersVO.from(1);
    value.users(vo);
    Assertions.assertSame(holder, value.unsetUsersIfMatches("users_other"));
    Assertions.assertTrue(value.getUsersValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetUsersIfMatches("users"));
    Assertions.assertFalse(value.getUsersValue().isPresent(),
        "The field name must clear the value");
    value.users(vo);
    Assertions.assertSame(holder, value.unsetUsers());
    Assertions.assertFalse(value.getUsersValue().isPresent(), "Unset must clear the value");
  }
}
